import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        String inputLine = scanner.nextLine();
        char[] chars = inputLine.toCharArray();
        int len = inputLine.length();

        String[] suffixes = {"00", "25", "50", "75"};
        int result = 0;

        if (chars.length == 1) {
            if (chars[0] == '0' || chars[0] == 'X' || chars[0] == '_') result++;
        } else {
            for (String suffix : suffixes) {
                int fixedDigit = -1;
                int idx = 0;
                boolean isPossible = true;
                for (int i = len - 2; i < len; i++) {
                    char currentChar = chars[i];
                    char expectedChar = suffix.charAt(idx++);
                    if (currentChar == '_') continue;
                    else if (currentChar == 'X') {
                        if (fixedDigit == -1) fixedDigit = expectedChar - '0';
                        else if (fixedDigit != expectedChar - '0') {
                            isPossible = false;
                            break;
                        }
                    } else if (currentChar != expectedChar) {
                        isPossible = false;
                        break;
                    }
                }
                if (!isPossible) continue;
                if (len == 2) {
                    if (suffix.charAt(0) == '0') continue;
                    result++;
                    continue;
                }
                char[] tempChars = Arrays.copyOf(chars, len);
                int countX = 0;
                for (char c : chars) if (c == 'X') countX++;
                if (fixedDigit != -1 || countX == 0) {
                    if (fixedDigit != -1) {
                        for (int k = 0; k < len; k++) {
                            if (chars[k] == 'X') tempChars[k] = (char) (fixedDigit + '0');
                        }
                    }
                    if (tempChars[0] == '0') continue;
                    int ways = 1;
                    for (int k = 0; k < len - 2; k++) {
                        if (tempChars[k] == '_') {
                            ways *= (k == 0) ? 9 : 10;
                        }
                    }
                    result += ways;
                } else {
                    if (tempChars[0] == '0') continue;
                    int ways = 1;
                    for (int k = 0; k < len - 2; k++) {
                        if (tempChars[k] == '_') {
                            ways *= (k == 0) ? 9 : 10;
                        }
                    }
                    if (tempChars[0] == 'X') {
                        ways *= 9;
                    } else {
                        ways *= 10;
                    }
                    result += ways;
                }
            }
        }
        writer.println(result);
        writer.close();
    }
}
